import{_ as d,r as o,o as a,c,e as t,a as s,s as l}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Directory Structure - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Root Directory","slug":"root-directory","link":"#root-directory","children":[{"level":3,"title":"Bootstrap Directory","slug":"bootstrap-directory","link":"#bootstrap-directory","children":[]},{"level":3,"title":"Config Directory","slug":"config-directory","link":"#config-directory","children":[]},{"level":3,"title":"Modules Directory","slug":"modules-directory","link":"#modules-directory","children":[]},{"level":3,"title":"Plugins Directory","slug":"plugins-directory","link":"#plugins-directory","children":[]},{"level":3,"title":"Storage Directory","slug":"storage-directory","link":"#storage-directory","children":[]},{"level":3,"title":"Themes Directory","slug":"themes-directory","link":"#themes-directory","children":[]},{"level":3,"title":"Vendor Directory","slug":"vendor-directory","link":"#vendor-directory","children":[]}]},{"level":2,"title":"Modules Directory","slug":"modules-directory-1","link":"#modules-directory-1","children":[{"level":3,"title":"System Module","slug":"system-module","link":"#system-module","children":[]},{"level":3,"title":"CMS Module","slug":"cms-module","link":"#cms-module","children":[]},{"level":3,"title":"Backend Module","slug":"backend-module","link":"#backend-module","children":[]},{"level":3,"title":"Editor Module","slug":"editor-module","link":"#editor-module","children":[]},{"level":3,"title":"Media Module","slug":"media-module","link":"#media-module","children":[]}]}],"relativePath":"2.x/setup/structure.md","filePath":"2.x/setup/structure.md"}'),n={name:"2.x/setup/structure.md"};function h(u,e,m,y,p,f){const r=o("pre-heading"),i=o("post-heading");return a(),c("div",null,[t(r),e[0]||(e[0]=s("h1",null,"Directory Structure",-1)),t(i),e[1]||(e[1]=l('<p>There are many different moving parts that come together to make the October CMS platform work. By default October CMS uses a modular structure where most programming features are found in either the modules or plugin directory. The only required module is the system module.</p><h2 id="root-directory"><a href="#root-directory" class="header-anchor">#</a> Root Directory</h2><h3 id="bootstrap-directory"><a href="#bootstrap-directory" class="header-anchor">#</a> Bootstrap Directory</h3><p>The <code>bootstrap</code> directory contains the <code>app.php</code> bootstrapper file that loads the Laravel framework. The directory also contains the custom autoloader used by the application, this is pulled in by any script that needs to load files within the application. You should not typically need to modify any files within this directory.</p><h3 id="config-directory"><a href="#config-directory" class="header-anchor">#</a> Config Directory</h3><p>The <code>config</code> directory contains all the application configuration files. Each file controls how the application functions and it is a good idea to get familiar with each file and its contents. These belong to your application and can be modified however you wish, they will not be touched during system updates.</p><h3 id="modules-directory"><a href="#modules-directory" class="header-anchor">#</a> Modules Directory</h3><p>The <code>modules</code> directory contains the core packages that are included with October CMS, providing <a href="#oc-modules-directory">core functionality</a> that is common across the system. Modules are loaded automatically based on their presence in the file system by default, however, you can manually specify which modules to load with the <code>system.load_modules</code> configuration item. The system module must be loaded at a minimum for the application to operate.</p><h3 id="plugins-directory"><a href="#plugins-directory" class="header-anchor">#</a> Plugins Directory</h3><p>The <code>plugins</code> directory contains packages that extend the core functionality of October CMS. Similar to modules, they can modify the platform by introducing new features or by extending other plugins. Plugins are loaded automatically when they are found in the filesystem, however, you can manually disable plugins using the <code>system.disable_plugins</code> configuration item.</p><h3 id="storage-directory"><a href="#storage-directory" class="header-anchor">#</a> Storage Directory</h3><p>The <code>storage</code> directory contains log files, cache files, sessions and other files generated by October CMS. The inner directory is segregated in to <code>app</code>, <code>cms</code>, <code>framework</code>, <code>logs</code> and <code>temp</code>.</p><p>The <code>app</code> storage directory contains application specific storage items, such as media files, file uploads and automatically generated resources, such as resized files and combined asset files. The <code>framework</code> storage directory is used by the Laravel framework to store its generated files and caches. The <code>cms</code> storage directory is used by the October CMS platform to store its generated files and caches. The <code>logs</code> storage directory contains your application&#39;s log files. The <code>temp</code> storage directory is a working directory used by the application.</p><h3 id="themes-directory"><a href="#themes-directory" class="header-anchor">#</a> Themes Directory</h3><p>The <code>themes</code> directory contains static file content that is used to manage the front end structure of your website. The active theme is set using the <code>cms.active_theme</code> configuration item.</p><h3 id="vendor-directory"><a href="#vendor-directory" class="header-anchor">#</a> Vendor Directory</h3><p>The <code>vendor</code> directory contains packages are included via Composer in either the project&#39;s <code>/vendor</code> directory or can sometimes be found in plugin-specific <code>/vendor</code> directories. The project vendor directory takes priority over and plugin vendor directories that appear in the system.</p><p><a id="oc-modules-directory"></a></p><h2 id="modules-directory-1"><a href="#modules-directory-1" class="header-anchor">#</a> Modules Directory</h2><h3 id="system-module"><a href="#system-module" class="header-anchor">#</a> System Module</h3><p>The <code>system</code> module contains the core functionality of October CMS and is a required module. It has shared logic that is used by other modules.</p><h3 id="cms-module"><a href="#cms-module" class="header-anchor">#</a> CMS Module</h3><p>The <code>cms</code> module introduces functionality for rendering frontend pages and loading themes. It is responsible for routing to pages, rendering partials and handling AJAX requests.</p><h3 id="backend-module"><a href="#backend-module" class="header-anchor">#</a> Backend Module</h3><p>The <code>backend</code> module is responsible for rendering backend pages and orchestrating menus, layouts and other administrative features.</p><h3 id="editor-module"><a href="#editor-module" class="header-anchor">#</a> Editor Module</h3><p>The <code>editor</code> module introduces a code editor to the backend interface of October CMS. It allows you to manage the website theme directly in the backend.</p><h3 id="media-module"><a href="#media-module" class="header-anchor">#</a> Media Module</h3><p>The <code>media</code> module introduces a media management feature to the backend interface of October CMS. It allows you to upload media files for inclusion in other areas.</p>',29))])}const k=d(n,[["render",h]]);export{b as __pageData,k as default};
